CREATE TABLE IF NOT EXISTS product_categories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,slug text NOT NULL UNIQUE,parent_id uuid REFERENCES product_categories(id),description text,sort_order integer NOT NULL DEFAULT 0,status text NOT NULL DEFAULT 'active',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS product_specifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),product_id uuid NOT NULL REFERENCES products(id),name text NOT NULL,value text NOT NULL,sort_order integer NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS media(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),url text NOT NULL UNIQUE,kind text NOT NULL,filename text,alt_text text,file_size bigint,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS product_media(product_id uuid NOT NULL REFERENCES products(id),media_id uuid NOT NULL REFERENCES media(id),sort_order integer NOT NULL DEFAULT 0,PRIMARY KEY(product_id,media_id));
CREATE TABLE IF NOT EXISTS content_categories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,slug text NOT NULL UNIQUE,type text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS content_tags(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL UNIQUE,slug text NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS form_fields(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),form_id uuid NOT NULL REFERENCES forms(id),label text NOT NULL,name text NOT NULL,type text NOT NULL,required boolean NOT NULL DEFAULT false,options jsonb NOT NULL DEFAULT '[]'::jsonb,sort_order integer NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS form_submissions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),form_id uuid REFERENCES forms(id),lead_id uuid REFERENCES leads(id),payload jsonb NOT NULL,source text,country text,landing_page text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS seo_keywords(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),keyword text NOT NULL,country text,language text,intent text,target_url text,status text NOT NULL DEFAULT 'active',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS geo_results(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),geo_query_id uuid NOT NULL REFERENCES geo_queries(id),platform text NOT NULL,mentioned boolean,position integer,citation_url text,competitors jsonb NOT NULL DEFAULT '[]'::jsonb,checked_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES users(id),type text NOT NULL,title text NOT NULL,body text,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS site_settings(key text PRIMARY KEY,value jsonb NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
